function extractJsonText(value) {
  if (typeof value !== 'string') {
    return JSON.stringify(value);
  }

  let text = value.trim();

  // Убираем ```json ... ```
  if (text.startsWith('```')) {
    text = text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .replace('\n', '')
      .replace('\\', '')
      .trim();
  }

  return text;
}

function normalizePostType(value) {
  const allowed = ['signal', 'result', 'announcement', 'noise'];
  if (typeof value !== 'string') return 'noise';

  const normalized = value.trim().toLowerCase();
  return allowed.includes(normalized) ? normalized : 'noise';
}

function normalizeDirection(value) {
  if (typeof value !== 'string') return null;

  const v = value.trim().toLowerCase();

  if (['long', 'buy', 'bullish'].includes(v)) return 'long';
  if (['short', 'sell', 'bearish'].includes(v)) return 'short';

  return null;
}

function normalizeTicker(value) {
  if (typeof value !== 'string') return null;

  const v = value.trim().toUpperCase().replace(/^[$#]/, '');

  // Для MVP: только латинские тикеры 2-10 символов
  if (/^[A-Z0-9]{2,10}$/.test(v)) {
    return v;
  }

  return null;
}

function normalizeConfidence(value) {
  let num = Number(value);

  if (Number.isNaN(num)) return 0.5;

  // Если модель вернула 96 вместо 0.96
  if (num > 1 && num <= 100) {
    num = num / 100;
  }

  if (num < 0) num = 0;
  if (num > 1) num = 1;

  return Math.round(num * 1000) / 1000;
}

const item = $input;
const src = item;

// Тут надо подставить поле, где реально лежит ответ AI.
// Часто это что-то вроде:
// src.output
// src.text
// src.response
// src.data
const rawAiOutput = src.content;

let parsed;
let parseError = null;

try {
  const jsonText = extractJsonText(rawAiOutput);
  parsed = JSON.parse(jsonText);
} catch (error) {
  parseError = error.message;
  parsed = null;
}

// fallback, если JSON вообще не распарсился
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return {
    json: {
      // ...src,
      ai_validation: {
        validated: false,
        error_stage: 'json_parse',
        error_message: parseError || 'AI output is not a valid JSON object',
        raw_ai_output: rawAiOutput,
      },
      classification: {
        message_id: src.message_id ?? null,
        post_type: 'noise',
        is_signal: false,
        ticker: null,
        direction: null,
        confidence: 0,
        reason: 'Fallback: invalid AI JSON',
      },
    },
  };
}

const postType = normalizePostType(parsed.post_type);
const direction = normalizeDirection(parsed.direction);
const ticker = normalizeTicker(parsed.ticker);
const confidence = normalizeConfidence(parsed.confidence);

const isSignal =
  typeof parsed.is_signal === 'boolean'
    ? parsed.is_signal
    : postType === 'signal';

const reason =
  typeof parsed.reason === 'string' && parsed.reason.trim()
    ? parsed.reason.trim()
    : 'No reason provided';

const messageId =
  parsed.message_id ?? src.message_id ?? null;

// Дополнительная логическая коррекция:
// если post_type != signal, то direction и ticker можно занулять,
// чтобы не тащить шум дальше
const finalTicker = postType === 'signal' ? ticker : null;
const finalDirection = postType === 'signal' ? direction : null;
const finalIsSignal = postType === 'signal' && isSignal ? true : false;

const validationWarnings = [];

if (parsed.post_type !== postType) {
  validationWarnings.push(`post_type normalized: ${parsed.post_type} -> ${postType}`);
}
if (parsed.direction !== finalDirection) {
  validationWarnings.push(`direction normalized: ${parsed.direction} -> ${finalDirection}`);
}
if (parsed.ticker !== finalTicker) {
  validationWarnings.push(`ticker normalized: ${parsed.ticker} -> ${finalTicker}`);
}
if (parsed.confidence !== confidence) {
  validationWarnings.push(`confidence normalized: ${parsed.confidence} -> ${confidence}`);
}

return {
  json: {
    // ...src,
    ai_validation: {
      validated: true,
      warnings: validationWarnings,
      raw_ai_output: rawAiOutput,
    },
    classification: {
      message_id: messageId,
      post_type: postType,
      is_signal: finalIsSignal,
      ticker: finalTicker,
      direction: finalDirection,
      confidence,
      reason,
    },
  },
};
